import numpy as np

SYMBOLS = ".abcdefghijklmnopqrstuvwxyz"
_ROWS = {0: [0, 0.5, 0.3, 0.2], 1: [0.4, 0.1, 0.3, 0.2], 2: [0.3, 0.5, 0.0, 0.2], 3: [0.6, 0.2, 0.2, 0.0]}


def toy(context):
    # a planted model over ., a, b, c that looks only at the last symbol
    return np.array(_ROWS[context[-1]] + [0.0] * 23)


def only_a(context):
    # a model that never ends a name
    p = np.zeros(27)
    p[1] = 1.0
    return p


def tenths(context):
    # ten letters at 0.1 each: the running total ends at 0.9999999999999999
    p = np.zeros(27)
    p[17:27] = 0.1
    return p


class FixedU:
    # stands in for a generator: hands out the given u values in turn
    def __init__(self, us):
        self.us = list(us)

    def random(self):
        return self.us.pop(0)

import json
_W = {k: np.array(v) for k, v in json.load(open('makemore-mlp.json')).items() if k != 'about'}


def mlp_logits(context):
    e = _W["C"][np.array(context)].reshape(-1)
    return np.tanh(e @ _W["W1"] + _W["b1"]) @ _W["W2"] + _W["b2"]


def mlp(context):
    z = mlp_logits(context)
    p = np.exp(z - z.max())
    return p / p.sum()

words = open('names.txt').read().splitlines()
perm = np.random.default_rng(42).permutation(len(words))
train = [words[i] for i in perm[:25626]]
dev500 = [words[i] for i in perm[25626:28829]][:500]
test500 = [words[i] for i in perm[28829:]][:500]
_N = np.zeros((27, 27))
for _w in train:
    _s = "." + _w + "."
    for _a, _b in zip(_s, _s[1:]):
        _N[SYMBOLS.index(_a), SYMBOLS.index(_b)] += 1
_P = (_N + 1) / (_N + 1).sum(axis=1, keepdims=True)


def bigram(context):
    return _P[context[-1]]


def flat(context):
    return np.full(27, 1 / 27)


class Counted:
    # wraps a model and counts how many contexts it is asked about
    def __init__(self, fn):
        self.fn, self.calls = fn, 0

    def __call__(self, context):
        self.calls += 1
        return self.fn(context)



def test_calls(models, dev, test):
    # contexts each model is asked about on the test names alone
    a = {k: Counted(v) for k, v in models.items()}
    evaluate_and_choose(a, dev, [])
    b = {k: Counted(v) for k, v in models.items()}
    evaluate_and_choose(b, dev, test)
    return sorted(b[k].calls - a[k].calls for k in models)

